/* T8140 DCS performance controls/counters: driver replay, declared profile,
 * rejected accesses and matched layout, against an independent shadow model.
 * The driver descriptor table is generated by the Python runner from the
 * pinned BootKC descriptor dump (dcs-perf-descriptors.h); this file checks its
 * derivation invariants before replaying the AppleT8140MCC register sequences.
 * v3: the optional dcs-channel-enable-mask / amcc-plane-enable-mask guards.
 * v4: optional-property rejections are matched exactly with the "DCS
 * performance" prefix (separate wrong-size and unmodelled-value messages).
 * SPDX-License-Identifier: AGPL-3.0-or-later */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "hw/arm/apple-silicon/modern-mcc-dcs-perf.h"
#include "dcs-perf-descriptors.h"

static unsigned checks;
#define CHECK(c) do { checks++; if (!(c)) { \
    fprintf(stderr, "FAIL %u: %s\n", __LINE__, #c); exit(1); } } while (0)
#include "test-apple-modern-mcc-optional-props.h"

#define BANKS 3
#define CONTROLS 64
#define EVENTS 10
#define DURATIONS 4
#define COUNTERS 14
#define RESET UINT64_C(0xfedcba9876543210)
#define CLEAR UINT32_C(0x11110000)
#define CONTROL_BASE 0x580U
#define COUNTER_BASE 0x4000U

/* The core sits between two guard words so exact aliasing bounds are testable. */
static struct Box {
    uint64_t head;
    AppleModernDCSPERFCore core;
    uint64_t tail;
} box;
static AppleModernDCSPERFCore *const dut = &box.core;

/* Independent shadow of the declared functional profile. */
typedef struct Shadow {
    uint32_t controls[BANKS][CONTROLS];
    uint64_t values[BANKS][COUNTERS];
    uint64_t reset_value, reads, writes, clears, updates;
} Shadow;
static Shadow model;

static void bump(uint64_t *value)
{
    if (*value != UINT64_MAX) {
        (*value)++;
    }
}

static void same(void)
{
    CHECK(!memcmp(dut->controls, model.controls, sizeof(model.controls)));
    CHECK(!memcmp(dut->values, model.values, sizeof(model.values)));
    CHECK(dut->reset_value == model.reset_value && dut->reads == model.reads &&
          dut->writes == model.writes && dut->clears == model.clears &&
          dut->event_updates == model.updates);
}

static void model_reset(void)
{
    memset(model.controls, 0, sizeof(model.controls));
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned i = 0; i < COUNTERS; i++) {
            model.values[b][i] = model.reset_value;
        }
    }
    model.reads = model.writes = model.clears = model.updates = 0;
}

static void model_write(unsigned bank, unsigned index, uint32_t word)
{
    if (index == 2) {
        for (unsigned i = 0; i < DURATIONS; i++) {
            if (word >> (16 + 4 * i) & 1) {
                model.values[bank][EVENTS + i] = 0;
                bump(&model.clears);
            }
        }
        word &= ~CLEAR;
    }
    model.controls[bank][index] = word;
    bump(&model.writes);
}

static void model_event(unsigned bank, unsigned counter, uint64_t amount)
{
    uint32_t gate = counter < EVENTS ? model.controls[bank][1] >> counter :
                    model.controls[bank][2] >> (4 * (counter - EVENTS));
    if (amount && (gate & 1)) {
        model.values[bank][counter] += amount;
        bump(&model.updates);
    }
}

static uint32_t ctl_read(unsigned bank, uint32_t reg)
{
    uint64_t value = UINT64_C(0xa5a5a5a5a5a5a5a5);
    CHECK(bank < BANKS && reg >= CONTROL_BASE && reg < CONTROL_BASE + 4 * CONTROLS &&
          !(reg & 3));
    CHECK(apple_modern_dcs_perf_core_read(dut, bank * 2, reg - CONTROL_BASE, 4, &value));
    CHECK(value == model.controls[bank][(reg - CONTROL_BASE) / 4]);
    bump(&model.reads);
    same();
    return (uint32_t)value;
}

static void ctl_write(unsigned bank, uint32_t reg, uint32_t word)
{
    CHECK(bank < BANKS && reg >= CONTROL_BASE && reg < CONTROL_BASE + 4 * CONTROLS &&
          !(reg & 3));
    CHECK(apple_modern_dcs_perf_core_write(dut, bank * 2, reg - CONTROL_BASE, 4, word));
    model_write(bank, (reg - CONTROL_BASE) / 4, word);
    same();
}

static uint64_t ctr_read(unsigned bank, uint32_t reg)
{
    uint64_t value = UINT64_C(0x5a5a5a5a5a5a5a5a);
    CHECK(bank < BANKS && reg >= COUNTER_BASE && reg < COUNTER_BASE + 8 * COUNTERS &&
          !(reg & 7));
    CHECK(apple_modern_dcs_perf_core_read(dut, bank * 2 + 1, reg - COUNTER_BASE, 8, &value));
    CHECK(value == model.values[bank][(reg - COUNTER_BASE) / 8]);
    bump(&model.reads);
    same();
    return value;
}

/* Driver slot 0x7b0: one read32 and one write32, (old & ~mask) | (value & mask). */
static uint32_t rmw(unsigned bank, uint32_t reg, uint32_t mask, uint32_t value)
{
    uint32_t old = ctl_read(bank, reg);
    ctl_write(bank, reg, (old & ~mask) | (value & mask));
    return old;
}

static void inject(unsigned bank, unsigned counter, uint64_t amount)
{
    CHECK(apple_modern_dcs_perf_core_event(dut, bank, counter, amount));
    model_event(bank, counter, amount);
    same();
}

static unsigned polls_seen;

/* Driver slot 0x770 -> 0x758: read64 of the counter, then the kind path. */
static void dispatch(const DCSDescriptor *d, bool enable)
{
    ctr_read(d->bank, d->counter);
    if (d->kind == 5) {
        uint32_t last;
        unsigned polls = 0;
        rmw(d->bank, d->select_reg, d->select_mask, d->select_value);
        rmw(d->bank, d->data_reg, d->request, d->request);
        do {
            last = ctl_read(d->bank, d->data_reg);
            polls++;
        } while ((last & d->request) && polls < 10);
        /* The driver panics after ten reads; the model clears at once. */
        CHECK(polls == 1 && !(last & d->request));
        polls_seen += polls;
        ctl_write(d->bank, d->data_reg, (last & ~d->enable) | (enable ? d->enable : 0));
    } else {
        CHECK(d->kind == 3 || d->kind == 4);
        if (enable && d->command_reg != UINT32_MAX) {
            rmw(d->bank, d->command_reg, d->command_value, d->command_value);
        }
        rmw(d->bank, d->enable_reg, d->enable, enable ? d->enable : 0);
    }
}

/* Driver slot 0x700: configure (kinds 3/4) then enable, in table order. */
static void program_and_enable_all(void)
{
    for (unsigned i = 0; i < DCS_DESCRIPTOR_COUNT; i++) {
        const DCSDescriptor *d = &dcs_descriptors[i];
        if (d->kind == 3 || d->kind == 4) {
            for (unsigned w = 0; w < d->param_count && w < 6; w++) {
                ctl_write(d->bank, d->data_reg + 4 * w, d->params[w]);
            }
        }
        dispatch(d, true);
    }
}

/* Driver slot 0x718 with its flag set: sample (read64), then disable. */
static void sample_and_disable_all(void)
{
    for (unsigned i = 0; i < DCS_DESCRIPTOR_COUNT; i++) {
        ctr_read(dcs_descriptors[i].bank, dcs_descriptors[i].counter);
        dispatch(&dcs_descriptors[i], false);
    }
}

static unsigned popcount4(unsigned value)
{
    return (value & 1) + (value >> 1 & 1) + (value >> 2 & 1) + (value >> 3 & 1);
}

static void check_descriptors(void)
{
    unsigned events[BANKS] = {0}, durations[BANKS] = {0}, kinds[8] = {0};
    CHECK(DCS_DESCRIPTOR_COUNT == 39);
    for (unsigned i = 0; i < DCS_DESCRIPTOR_COUNT; i++) {
        const DCSDescriptor *d = &dcs_descriptors[i];
        unsigned ch = d->channel;
        CHECK(d->index == i && d->bank < BANKS && d->kind < 8);
        kinds[d->kind]++;
        if (d->kind == 3 || d->kind == 4) {
            CHECK(ch == events[d->bank]++ && ch < EVENTS);
            CHECK(d->enable_reg == 0x584 && d->enable == 1U << ch);
            CHECK(d->command_reg == 0x580 && d->command_value == ((1U << (ch + 4)) | 1));
            CHECK(d->data_reg == 0x590 + 0x18 * ch && d->param_count == 6);
            CHECK(d->counter == COUNTER_BASE + 8 * ch);
            CHECK(d->data_reg + 4 * 6 <= CONTROL_BASE + 4 * CONTROLS);
        } else {
            CHECK(d->kind == 5 && ch < DURATIONS && !(durations[d->bank] >> ch & 1));
            durations[d->bank] |= 1U << ch;
            CHECK(d->select_reg == 0x58c && d->data_reg == 0x588);
            CHECK(d->select_mask == UINT32_C(0x3f) << (8 * ch));
            CHECK(!(d->select_value & ~d->select_mask) && d->select_value);
            CHECK(d->request == UINT32_C(0x10000) << (4 * ch));
            CHECK(d->enable == 1U << (4 * ch));
            CHECK(d->counter == COUNTER_BASE + 8 * (EVENTS + ch));
        }
    }
    CHECK(events[0] == 10 && events[1] == 10 && events[2] == 7);
    CHECK(durations[0] == 0xf && durations[1] == 0xf && durations[2] == 0xf);
    CHECK(kinds[3] == 13 && kinds[4] == 14 && kinds[5] == 12);
}

static void fresh_reset(uint64_t reset_value)
{
    memset(&box, 0x5a, sizeof(box));
    dut->reset_value = reset_value;
    apple_modern_dcs_perf_core_reset(dut);
    CHECK(box.head == UINT64_C(0x5a5a5a5a5a5a5a5a) &&
          box.tail == UINT64_C(0x5a5a5a5a5a5a5a5a));
    model.reset_value = reset_value;
    model_reset();
    same();
}

static void core_tests(void)
{
    static const uint32_t command[BANKS] = {0x3ff1, 0x3ff1, 0x7f1};
    static const uint32_t enables[BANKS] = {0x3ff, 0x3ff, 0x7f};
    static const uint32_t select[BANKS] = {0x023f023f, 0x08040804, 0x20102010};
    uint64_t value, r0, w0, c0;

    CHECK((uint8_t *)&box.core == (uint8_t *)&box.head + 8);
    CHECK((uint8_t *)&box.tail == (uint8_t *)&box.core + sizeof(box.core));
    fresh_reset(RESET);
    /* Reset: every control 0, every counter the virtual reset value. */
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned k = 0; k < CONTROLS; k++) {
            CHECK(ctl_read(b, CONTROL_BASE + 4 * k) == 0);
        }
        for (unsigned c = 0; c < COUNTERS; c++) {
            CHECK(ctr_read(b, COUNTER_BASE + 8 * c) == RESET);
        }
    }
    CHECK(dut->reads == 234 && !dut->writes && !dut->clears && !dut->event_updates);
    check_descriptors();

    /* Boot sweep: exactly the 129 reads / 252 writes the pinned guest made. */
    r0 = dut->reads; w0 = dut->writes; c0 = dut->clears;
    program_and_enable_all();
    CHECK(dut->reads - r0 == 129 && dut->writes - w0 == 252 && dut->clears - c0 == 12);
    CHECK(polls_seen == 12);
    for (unsigned b = 0; b < BANKS; b++) {
        CHECK(ctl_read(b, 0x580) == command[b]);
        CHECK(ctl_read(b, 0x584) == enables[b]);
        CHECK(ctl_read(b, 0x588) == 0x1111);
        CHECK(ctl_read(b, 0x58c) == select[b]);
        for (unsigned c = 0; c < EVENTS; c++) {
            CHECK(ctr_read(b, COUNTER_BASE + 8 * c) == RESET);
        }
        for (unsigned i = 0; i < DURATIONS; i++) {
            CHECK(ctr_read(b, COUNTER_BASE + 8 * (EVENTS + i)) == 0);
        }
        for (unsigned ch = 7; b == 2 && ch < EVENTS; ch++) {
            for (unsigned w = 0; w < 6; w++) {
                CHECK(ctl_read(b, 0x590 + 0x18 * ch + 4 * w) == 0);
            }
        }
    }
    for (unsigned i = 0; i < DCS_DESCRIPTOR_COUNT; i++) {
        const DCSDescriptor *d = &dcs_descriptors[i];
        for (unsigned w = 0; d->kind != 5 && w < 6; w++) {
            CHECK(ctl_read(d->bank, d->data_reg + 4 * w) == d->params[w]);
        }
    }
    /* Enable bits persist and do not self-clear. */
    for (unsigned repeat = 0; repeat < 8; repeat++) {
        for (unsigned b = 0; b < BANKS; b++) {
            CHECK(ctl_read(b, 0x584) == enables[b] && ctl_read(b, 0x588) == 0x1111);
        }
    }

    /* Event injection gated by the driver-programmed enables. */
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned c = 0; c < COUNTERS; c++) {
            uint64_t before = dut->values[b][c], amount = 0x1000 + b * 0x100 + c;
            bool enabled = c >= EVENTS || b < 2 || c < 7;
            inject(b, c, amount);
            CHECK(dut->values[b][c] == (enabled ? before + amount : before));
        }
    }
    CHECK(dut->event_updates == 39);
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned c = 0; c < COUNTERS; c++) {
            inject(b, c, 0);
        }
    }
    CHECK(dut->event_updates == 39);

    /* Save path: sample and disable; command and select persist. */
    r0 = dut->reads; w0 = dut->writes; c0 = dut->clears;
    sample_and_disable_all();
    CHECK(dut->reads - r0 == 141 && dut->writes - w0 == 63 && dut->clears - c0 == 12);
    for (unsigned b = 0; b < BANKS; b++) {
        CHECK(ctl_read(b, 0x580) == command[b] && ctl_read(b, 0x584) == 0);
        CHECK(ctl_read(b, 0x588) == 0 && ctl_read(b, 0x58c) == select[b]);
        for (unsigned c = 0; c < EVENTS; c++) {
            bool enabled = b < 2 || c < 7;
            CHECK(dut->values[b][c] == RESET + (enabled ? 0x1000 + b * 0x100 + c : 0));
        }
        for (unsigned i = 0; i < DURATIONS; i++) {
            CHECK(!dut->values[b][EVENTS + i]);
        }
    }
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned c = 0; c < COUNTERS; c++) {
            uint64_t before = dut->values[b][c];
            inject(b, c, 77);
            CHECK(dut->values[b][c] == before);
        }
    }
    CHECK(dut->event_updates == 39);
    /* Restore path: the same sweep re-enables without clearing event counts. */
    r0 = dut->reads; w0 = dut->writes; c0 = dut->clears;
    program_and_enable_all();
    CHECK(dut->reads - r0 == 129 && dut->writes - w0 == 252 && dut->clears - c0 == 12);
    for (unsigned b = 0; b < BANKS; b++) {
        CHECK(dut->controls[b][0] == command[b] && dut->controls[b][1] == enables[b]);
        CHECK(dut->controls[b][2] == 0x1111 && dut->controls[b][3] == select[b]);
    }

    /* Per-counter gating with exactly one enable bit, no leakage anywhere. */
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned c = 0; c < COUNTERS; c++) {
            uint64_t before[BANKS][COUNTERS];
            for (unsigned bb = 0; bb < BANKS; bb++) {
                ctl_write(bb, 0x584, 0);
                ctl_write(bb, 0x588, 0);
            }
            if (c < EVENTS) {
                ctl_write(b, 0x584, 1U << c);
            } else {
                ctl_write(b, 0x588, 1U << (4 * (c - EVENTS)));
            }
            memcpy(before, dut->values, sizeof(before));
            for (unsigned bb = 0; bb < BANKS; bb++) {
                for (unsigned cc = 0; cc < COUNTERS; cc++) {
                    inject(bb, cc, 3);
                }
            }
            for (unsigned bb = 0; bb < BANKS; bb++) {
                for (unsigned cc = 0; cc < COUNTERS; cc++) {
                    CHECK(dut->values[bb][cc] ==
                          before[bb][cc] + (bb == b && cc == c ? 3 : 0));
                }
            }
        }
    }
    /* Non-gating bits of either enable register gate nothing. */
    for (unsigned b = 0; b < BANKS; b++) {
        ctl_write(b, 0x584, UINT32_C(0xfffffc00));
        ctl_write(b, 0x588, UINT32_C(0xeeeeeeee));
        CHECK(ctl_read(b, 0x588) == UINT32_C(0xeeeeeeee));
    }
    {
        uint64_t before[BANKS][COUNTERS], updates = dut->event_updates;
        memcpy(before, dut->values, sizeof(before));
        for (unsigned b = 0; b < BANKS; b++) {
            for (unsigned c = 0; c < COUNTERS; c++) {
                inject(b, c, 5);
            }
        }
        CHECK(!memcmp(before, dut->values, sizeof(before)) && dut->event_updates == updates);
    }
    /* Unsigned modulo-2^64 accumulation. */
    ctl_write(1, 0x584, 1U << 4);
    ctl_write(1, 0x588, 1U << 8);
    for (unsigned c = 4; c <= 12; c += 8) {
        uint64_t x = dut->values[1][c];
        inject(1, c, UINT64_MAX);
        CHECK(dut->values[1][c] == x - 1);
        inject(1, c, 0 - (x - 1));
        CHECK(dut->values[1][c] == 0);
        inject(1, c, 1);
        CHECK(dut->values[1][c] == 1);
    }

    /* Clear bits: each zeroes exactly its duration counter in its bank. */
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned set = 0; set < 16; set++) {
            uint64_t before[BANKS][COUNTERS];
            uint32_t word = UINT32_C(0xeeeeffff);
            for (unsigned bb = 0; bb < BANKS; bb++) {
                ctl_write(bb, 0x584, 0x3ff);
                ctl_write(bb, 0x588, 0x1111);
                for (unsigned c = 0; c < COUNTERS; c++) {
                    inject(bb, c, 0x100 * (bb + 1) + c + 1 + set);
                }
            }
            for (unsigned i = 0; i < DURATIONS; i++) {
                word |= (set >> i & 1) << (16 + 4 * i);
            }
            memcpy(before, dut->values, sizeof(before));
            c0 = dut->clears;
            ctl_write(b, 0x588, word);
            CHECK(dut->clears - c0 == popcount4(set));
            CHECK(ctl_read(b, 0x588) == UINT32_C(0xeeeeffff));
            for (unsigned bb = 0; bb < BANKS; bb++) {
                for (unsigned c = 0; c < COUNTERS; c++) {
                    bool cleared = bb == b && c >= EVENTS && (set >> (c - EVENTS) & 1);
                    CHECK(before[bb][c] && dut->values[bb][c] == (cleared ? 0 : before[bb][c]));
                }
            }
        }
    }
    /* The same bit pattern anywhere else is plain storage. */
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned k = 0; k < CONTROLS; k++) {
            uint64_t before[BANKS][COUNTERS];
            if (k == 2) {
                continue;
            }
            memcpy(before, dut->values, sizeof(before));
            c0 = dut->clears;
            ctl_write(b, CONTROL_BASE + 4 * k, CLEAR);
            CHECK(ctl_read(b, CONTROL_BASE + 4 * k) == CLEAR);
            CHECK(dut->clears == c0 && !memcmp(before, dut->values, sizeof(before)));
        }
    }
    /* Controls store all 32 bits; only the +0x588 clear bits read as zero. */
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned k = 0; k < CONTROLS; k++) {
            uint32_t reg = CONTROL_BASE + 4 * k;
            for (unsigned bit = 0; bit < 32; bit++) {
                ctl_write(b, reg, 1U << bit);
                CHECK(ctl_read(b, reg) == (k == 2 && (CLEAR >> bit & 1) ? 0 : 1U << bit));
            }
            ctl_write(b, reg, UINT32_MAX);
            CHECK(ctl_read(b, reg) == (k == 2 ? ~CLEAR : UINT32_MAX));
        }
    }
    /* A 4-byte store keeps the low word (QEMU never supplies upper bits). */
    CHECK(apple_modern_dcs_perf_core_write(dut, 4, 0x10, 4, UINT64_C(0xffffffff12345678)));
    model_write(2, 4, 0x12345678);
    same();
    CHECK(ctl_read(2, 0x590) == 0x12345678);

    /* Rejected operations change nothing, byte for byte. */
    {
        struct Box before;
        unsigned views[] = {6, 7, 8, 100, UINT32_MAX};
        uint64_t offsets[] = {0, 4, 8, 0x58, 0x68, 0x6c, 0x70, 0xfc, 0x100, 0x104,
                              0x4000, UINT64_MAX - 7, UINT64_MAX - 3, UINT64_MAX};
        value = UINT64_C(0x0123456789abcdef);
        memcpy(&before, &box, sizeof(box));
        for (unsigned b = 0; b < BANKS; b++) {
            for (unsigned c = 0; c < COUNTERS; c++) {
                for (unsigned width = 0; width <= 16; width++) {
                    CHECK(!apple_modern_dcs_perf_core_write(dut, b * 2 + 1, c * 8, width,
                                                            UINT64_C(0xfeedfacecafebeef)));
                }
            }
        }
        for (unsigned view = 0; view < 6; view++) {
            unsigned width = view % 2 ? 8 : 4;
            uint64_t span = view % 2 ? 0x70 : 0x100;
            for (unsigned bad = 0; bad <= 16; bad++) {
                if (bad == width) {
                    continue;
                }
                CHECK(!apple_modern_dcs_perf_core_read(dut, view, 0, bad, &value));
                CHECK(!apple_modern_dcs_perf_core_write(dut, view, 0, bad, 1));
                CHECK(!apple_modern_dcs_perf_core_read(dut, view, span - width, bad, &value));
                CHECK(!apple_modern_dcs_perf_core_write(dut, view, span - width, bad, 1));
            }
            for (unsigned misaligned = 1; misaligned < width; misaligned++) {
                CHECK(!apple_modern_dcs_perf_core_read(dut, view, misaligned, width, &value));
                CHECK(!apple_modern_dcs_perf_core_write(dut, view, misaligned, width, 1));
                CHECK(!apple_modern_dcs_perf_core_read(dut, view, span - width + misaligned,
                                                       width, &value));
                CHECK(!apple_modern_dcs_perf_core_write(dut, view, span - width + misaligned,
                                                        width, 1));
            }
            for (unsigned i = 0; i < sizeof(offsets) / sizeof(offsets[0]); i++) {
                if (offsets[i] < span) {
                    continue;
                }
                CHECK(!apple_modern_dcs_perf_core_read(dut, view, offsets[i], width, &value));
                CHECK(!apple_modern_dcs_perf_core_write(dut, view, offsets[i], width, 1));
            }
            CHECK(!apple_modern_dcs_perf_core_read(dut, view, span, width, &value));
            CHECK(!apple_modern_dcs_perf_core_write(dut, view, span, width, 1));
            CHECK(!apple_modern_dcs_perf_core_read(dut, view, UINT64_MAX, width, &value));
            CHECK(!apple_modern_dcs_perf_core_write(dut, view, UINT64_MAX, width, 1));
            CHECK(!apple_modern_dcs_perf_core_read(NULL, view, 0, width, &value));
            CHECK(!apple_modern_dcs_perf_core_write(NULL, view, 0, width, 1));
            CHECK(!apple_modern_dcs_perf_core_read(dut, view, 0, width, NULL));
        }
        for (unsigned i = 0; i < sizeof(views) / sizeof(views[0]); i++) {
            for (unsigned width = 0; width <= 16; width++) {
                CHECK(!apple_modern_dcs_perf_core_read(dut, views[i], 0, width, &value));
                CHECK(!apple_modern_dcs_perf_core_write(dut, views[i], 0, width, 1));
            }
        }
        /* Output aliasing any part of the core is refused before any write. */
        uint64_t *inside[] = {(uint64_t *)(void *)&dut->controls[0][0],
                              (uint64_t *)(void *)&dut->controls[2][62],
                              &dut->values[0][0], &dut->values[2][13], &dut->reset_value,
                              &dut->reads, &dut->clears, &dut->event_updates};
        for (unsigned i = 0; i < sizeof(inside) / sizeof(inside[0]); i++) {
            CHECK(!apple_modern_dcs_perf_core_read(dut, 0, 0, 4, inside[i]));
            CHECK(!apple_modern_dcs_perf_core_read(dut, 5, 0x68, 8, inside[i]));
        }
        CHECK(!apple_modern_dcs_perf_core_event(NULL, 0, 0, 1));
        CHECK(!apple_modern_dcs_perf_core_event(dut, 3, 0, 1));
        CHECK(!apple_modern_dcs_perf_core_event(dut, UINT32_MAX, 0, 1));
        CHECK(!apple_modern_dcs_perf_core_event(dut, 0, 14, 1));
        CHECK(!apple_modern_dcs_perf_core_event(dut, 2, UINT32_MAX, 1));
        CHECK(value == UINT64_C(0x0123456789abcdef));
        CHECK(!memcmp(&before, &box, sizeof(box)));
        same();
    }
    /* Exact aliasing bounds: the words just outside the core are usable. */
    CHECK(apple_modern_dcs_perf_core_read(dut, 4, 0x10, 4, &box.head));
    CHECK(box.head == 0x12345678);
    bump(&model.reads);
    CHECK(apple_modern_dcs_perf_core_read(dut, 1, 0, 8, &box.tail));
    CHECK(box.tail == model.values[0][0]);
    bump(&model.reads);
    same();

    /* Diagnostics saturate; functional effects continue. */
    ctl_write(0, 0x588, 0x1111);
    ctl_write(0, 0x584, 0x3ff);
    dut->reads = dut->writes = dut->clears = dut->event_updates = UINT64_MAX - 1;
    model.reads = model.writes = model.clears = model.updates = UINT64_MAX - 1;
    for (unsigned repeat = 0; repeat < 2; repeat++) {
        ctl_read(0, 0x584);
        inject(0, 10, 9);
        inject(0, 1, 9);
        ctl_write(0, 0x588, 0x1111 | 0x10000);
        CHECK(dut->values[0][10] == 0 && ctl_read(0, 0x588) == 0x1111);
    }
    CHECK(dut->reads == UINT64_MAX && dut->writes == UINT64_MAX &&
          dut->clears == UINT64_MAX && dut->event_updates == UINT64_MAX);

    /* Reset clears controls and diagnostics and restores counter values. */
    apple_modern_dcs_perf_core_reset(dut);
    model_reset();
    same();
    for (unsigned b = 0; b < BANKS; b++) {
        for (unsigned k = 0; k < CONTROLS; k++) {
            CHECK(!dut->controls[b][k]);
        }
        for (unsigned c = 0; c < COUNTERS; c++) {
            CHECK(dut->values[b][c] == RESET);
        }
    }
    CHECK(!dut->reads && !dut->writes && !dut->clears && !dut->event_updates);
    fresh_reset(0);
    fresh_reset(UINT64_MAX);
    CHECK(ctr_read(2, 0x4068) == UINT64_MAX);
}

static void expect_error(Error **error, const char *substring)
{
    CHECK(*error != NULL);
    if (!strstr((*error)->message, substring)) {
        fprintf(stderr, "unexpected error: %s\n", (*error)->message);
    }
    CHECK(strstr((*error)->message, substring) != NULL);
    error_free(*error);
    *error = NULL;
}

static bool plan_zero(const AppleModernDCSPERFPlan *plan)
{
    for (unsigned i = 0; i < APPLE_MODERN_DCS_PERF_VIEWS; i++) {
        if (plan->addresses[i] || plan->spans[i]) {
            return false;
        }
    }
    return true;
}

static unsigned plan_trees;

static bool dcs_plan(AppleModernBlob tree, void *plan, Error **errp)
{
    return apple_modern_dcs_perf_plan_build(tree, UINT64_C(0x10000000000),
                                            UINT64_C(8) << 30, NULL, 0, plan, errp);
}

static void plan_tests(const char *path)
{
    FILE *file = fopen(path, "rb");
    CHECK(file);
    CHECK(!fseek(file, 0, SEEK_END));
    long length = ftell(file);
    CHECK(length > 0 && length < 1 << 20 && length % 8 == 0);
    rewind(file);
    uint8_t *tree = malloc(length), *original = malloc(length);
    CHECK(tree && original);
    CHECK(fread(tree, 1, length, file) == (size_t)length);
    fclose(file);
    memcpy(original, tree, length);
    AppleModernBlob blob = {tree, length}, property;
    AppleModernDCSPERFPlan plan, expected;
    AppleModernMCCDRAMCFGPlan geometry;
    Error *error = NULL;
    const uint64_t dram = UINT64_C(0x10000000000), size = UINT64_C(8) << 30;
    const uint64_t dcs3 = UINT64_C(0x220a00000);

    CHECK(apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
    CHECK(!error);
    CHECK(apple_modern_mcc_dramcfg_plan_build(blob, dram, size, NULL, 0, &geometry, &error));
    for (unsigned view = 0; view < 6; view++) {
        uint64_t base = UINT64_C(0x220400000) + (uint64_t)(view / 2) * 0x200000;
        uint64_t address = base + (view % 2 ? 0x4000 : 0x580);
        uint64_t span = view % 2 ? 0x70 : 0x100;
        CHECK(plan.addresses[view] == address && plan.spans[view] == span);
        CHECK(geometry.addresses[view / 2] - 0x1d48 == base);
        CHECK(address + span <= base + 0x8000);
        CHECK(address + span <= dcs3 || address >= dcs3 + 0x8000);
    }
    expected = plan;
    /* DCS3 is not mapped, and only the six sparse views are claimed. */
    {
        AppleModernAddressRange holes[10] = {{dcs3, 0x8000}};
        for (unsigned b = 0; b < 3; b++) {
            uint64_t base = UINT64_C(0x220400000) + (uint64_t)b * 0x200000;
            holes[1 + b * 3] = (AppleModernAddressRange){base, 0x580};
            holes[2 + b * 3] = (AppleModernAddressRange){base + 0x680, 0x4000 - 0x680};
            holes[3 + b * 3] = (AppleModernAddressRange){base + 0x4070, 0x8000 - 0x4070};
        }
        CHECK(apple_modern_dcs_perf_plan_build(blob, dram, size, holes, 10, &plan, &error));
        CHECK(!memcmp(&plan, &expected, sizeof(plan)));
    }
    for (unsigned view = 0; view < 6; view++) {
        uint64_t address = expected.addresses[view], span = expected.spans[view];
        AppleModernAddressRange last = {address + span - 1, 1}, first = {address, 1};
        AppleModernAddressRange bank = {address & ~UINT64_C(0x7fff), 0x8000};
        AppleModernAddressRange adjacent[] = {{address - 8, 8}, {address + span, 8}};
        AppleModernAddressRange tight[] = {{address - 1, 1}, {address + span, 1}};
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, &last, 1, &plan, &error));
        expect_error(&error, "DCS performance view overlaps another device");
        CHECK(plan_zero(&plan));
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, &first, 1, &plan, &error));
        expect_error(&error, "DCS performance view overlaps another device");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, &bank, 1, &plan, &error));
        expect_error(&error, "DCS performance view overlaps another device");
        CHECK(plan_zero(&plan));
        CHECK(apple_modern_dcs_perf_plan_build(blob, dram, size, adjacent, 2, &plan, &error));
        CHECK(!memcmp(&plan, &expected, sizeof(plan)));
        CHECK(apple_modern_dcs_perf_plan_build(blob, dram, size, tight, 2, &plan, &error));
        CHECK(!memcmp(&plan, &expected, sizeof(plan)));
        CHECK(!apple_modern_dcs_perf_plan_build(blob, address, span, NULL, 0, &plan, &error));
        expect_error(&error, "DCS performance view overlaps DRAM");
        CHECK(plan_zero(&plan));
        CHECK(!apple_modern_dcs_perf_plan_build(blob, address + span - 1, 1, NULL, 0, &plan,
                                               &error));
        expect_error(&error, "DCS performance view overlaps DRAM");
        CHECK(apple_modern_dcs_perf_plan_build(blob, address + span, 0x10, NULL, 0, &plan,
                                              &error));
        CHECK(!memcmp(&plan, &expected, sizeof(plan)));
        CHECK(apple_modern_dcs_perf_plan_build(blob, address - 0x10, 0x10, NULL, 0, &plan,
                                              &error));
        CHECK(!memcmp(&plan, &expected, sizeof(plan)));
    }
    /* Mutated matched-schema properties are rejected; restoring passes again. */
    {
        static const char *const names[] = {"compatible", "dcs-reg-idx",
                                            "dcs-count-per-amcc", "amcc-count"};
        for (unsigned i = 0; i < 4; i++) {
            CHECK(apple_modern_adt_property(blob, "/arm-io/mcc", names[i], &property, &error));
            uint8_t *byte = (uint8_t *)property.data;
            *byte ^= 1;
            CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
            expect_error(&error, "MCC DRAMCFG");
            CHECK(plan_zero(&plan));
            *byte ^= 1;
            /* A renamed (missing) property is rejected too. */
            byte = (uint8_t *)property.data - 36;
            *byte ^= 0x20;
            CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
            CHECK(error != NULL);
            error_free(error);
            error = NULL;
            CHECK(plan_zero(&plan));
            *byte ^= 0x20;
            CHECK(!memcmp(tree, original, length));
        }
        CHECK(apple_modern_adt_property(blob, "/arm-io/mcc", "reg", &property, &error));
        CHECK(property.size == 12 * 16);
        for (unsigned entry = 8; entry < 12; entry++) {
            for (unsigned field = 0; field < 2; field++) {
                uint8_t *byte = (uint8_t *)property.data + entry * 16 + field * 8;
                *byte ^= 1;
                CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan,
                                                       &error));
                expect_error(&error, "MCC DRAMCFG DCS bank");
                CHECK(plan_zero(&plan));
                *byte ^= 1;
            }
        }
        CHECK(apple_modern_adt_property(blob, "/arm-io", "ranges", &property, &error));
        CHECK(property.size >= 48 && property.size % 24 == 0);
        uint8_t *ranges = (uint8_t *)property.data, saved[24];
        memcpy(saved, ranges + 24, 24);
        memcpy(ranges + 24, ranges, 24);
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
        expect_error(&error, "MCC DRAMCFG bank is ambiguous");
        memcpy(ranges + 24, saved, 24);
        memcpy(saved, ranges, 24);
        ranges[8] ^= 1;
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
        expect_error(&error, "MCC DRAMCFG bank translation disagrees");
        memcpy(ranges, saved, 24);
        memset(ranges + 16, 0, 8);
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
        expect_error(&error, "MCC DRAMCFG bus range is empty or wraps");
        memset(ranges + 16, 0xff, 8);
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
        expect_error(&error, "MCC DRAMCFG bus range is empty or wraps");
        CHECK(plan_zero(&plan));
        memcpy(ranges, saved, 24);
        CHECK(!memcmp(tree, original, length));
    }
    /* Exclusion budget and validity. */
    {
        enum { MAX = APPLE_MODERN_MAX_BOARD_EXCLUSIONS };
        AppleModernAddressRange exclusions[MAX + 1], copy[MAX + 1];
        for (unsigned i = 0; i < MAX + 1; i++) {
            exclusions[i] = (AppleModernAddressRange){UINT64_C(0x1000) + i * 8, 8};
        }
        /* The pinned board budget is 64; a later tree may raise it. */
        CHECK(MAX >= 64);
        CHECK(apple_modern_dcs_perf_plan_build(blob, dram, size, exclusions, MAX, &plan, &error));
        CHECK(!memcmp(&plan, &expected, sizeof(plan)));
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, exclusions, MAX + 1, &plan,
                                               &error));
        expect_error(&error, "DCS performance output aliases input or exclusions are invalid");
        AppleModernAddressRange wrap = {UINT64_MAX, 8}, wrap2 = {UINT64_MAX - 7, 8};
        AppleModernAddressRange empty = {0x1000, 0}, top = {UINT64_MAX - 7, 7};
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, &wrap, 1, &plan, &error));
        expect_error(&error, "DCS performance exclusion is empty or wraps");
        CHECK(plan_zero(&plan));
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, &wrap2, 1, &plan, &error));
        expect_error(&error, "DCS performance exclusion is empty or wraps");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, &empty, 1, &plan, &error));
        expect_error(&error, "DCS performance exclusion is empty or wraps");
        CHECK(apple_modern_dcs_perf_plan_build(blob, dram, size, &top, 1, &plan, &error));
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 1, &plan, &error));
        expect_error(&error, "DCS performance output aliases input or exclusions are invalid");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, UINT64_MAX, size, NULL, 0, &plan, &error));
        expect_error(&error, "MCC DRAMCFG DRAM extent is empty or wraps");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, 0, NULL, 0, &plan, &error));
        expect_error(&error, "MCC DRAMCFG DRAM extent is empty or wraps");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, NULL, &error));
        expect_error(&error, "DCS performance output aliases input or exclusions are invalid");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, &wrap, 1, &plan, NULL));
        CHECK(plan_zero(&plan));
        /* Output aliasing the tree or the exclusions is refused before writing. */
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0,
              (AppleModernDCSPERFPlan *)(void *)tree, &error));
        expect_error(&error, "DCS performance output aliases input or exclusions are invalid");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0,
              (AppleModernDCSPERFPlan *)(void *)(tree + length - 8), &error));
        expect_error(&error, "DCS performance output aliases input or exclusions are invalid");
        CHECK(!memcmp(tree, original, length));
        memcpy(copy, exclusions, sizeof(copy));
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, exclusions, 1,
              (AppleModernDCSPERFPlan *)(void *)exclusions, &error));
        expect_error(&error, "DCS performance output aliases input or exclusions are invalid");
        CHECK(!apple_modern_dcs_perf_plan_build(blob, dram, size, exclusions + 1, 2,
              (AppleModernDCSPERFPlan *)(void *)exclusions, &error));
        expect_error(&error, "DCS performance output aliases input or exclusions are invalid");
        CHECK(!memcmp(copy, exclusions, sizeof(copy)));
        /* Missing or truncated trees are rejected. */
        AppleModernBlob none = {NULL, 0}, truncated = {tree, length / 2};
        CHECK(!apple_modern_dcs_perf_plan_build(none, dram, size, NULL, 0, &plan, &error));
        CHECK(error != NULL); error_free(error); error = NULL;
        CHECK(plan_zero(&plan));
        CHECK(!apple_modern_dcs_perf_plan_build(truncated, dram, size, NULL, 0, &plan, &error));
        CHECK(error != NULL); error_free(error); error = NULL;
        CHECK(plan_zero(&plan));
    }
    /* Optional /arm-io/mcc properties (absent from the matched trees): both
     * masks default to 0xf and gate which units the driver samples; the SLC
     * way cap is not a DCS input. */
    CHECK(!apple_modern_adt_property(blob, "/arm-io/mcc", "dcs-channel-enable-mask",
                                     &property, &error));
    CHECK(error != NULL); error_free(error); error = NULL;
    CHECK(!apple_modern_adt_property(blob, "/arm-io/mcc", "amcc-plane-enable-mask",
                                     &property, &error));
    CHECK(error != NULL); error_free(error); error = NULL;
    opt_device = "DCS performance";
    opt_property_sweep(tree, length, "dcs-channel-enable-mask", true, 0xf, dcs_plan,
                       &plan, sizeof(plan), &expected);
    opt_property_sweep(tree, length, "amcc-plane-enable-mask", true, 0xf, dcs_plan,
                       &plan, sizeof(plan), &expected);
    opt_ignored_sweep(tree, length, "max-way-count", dcs_plan, &plan, sizeof(plan), &expected);
    {
        static const struct { uint32_t dcs, amcc; const char *name, *value; } pairs[] = {
            {0xf, 0xf, NULL, NULL},
            {0x7, 0xf, "dcs-channel-enable-mask", "=0x7 "},
            {0xf, 0x7, "amcc-plane-enable-mask", "=0x7 "},
            /* The DCS mask is checked first. */
            {0x3, 0x1, "dcs-channel-enable-mask", "=0x3 "},
        };
        for (unsigned i = 0; i < sizeof(pairs) / sizeof(pairs[0]); i++) {
            OptTree copy = opt_copy(tree, length);
            opt_set(&copy, OPT_DONOR_A, "dcs-channel-enable-mask", pairs[i].dcs);
            opt_set(&copy, OPT_DONOR_C, "amcc-plane-enable-mask", pairs[i].amcc);
            opt_set(&copy, OPT_DONOR_B, "max-way-count", 0xffffffffU);
            opt_expect(&copy, dcs_plan, &plan, sizeof(plan), &expected, pairs[i].name,
                       pairs[i].value);
            free(copy.data);
        }
    }
    CHECK(opt_accepts && opt_rejects && opt_size_rejects);
    CHECK(apple_modern_dcs_perf_plan_build(blob, dram, size, NULL, 0, &plan, &error));
    CHECK(!memcmp(&plan, &expected, sizeof(plan)) && !memcmp(tree, original, length));
    free(original);
    free(tree);
    plan_trees++;
}

int main(int argc, char **argv)
{
    CHECK(argc >= 2);
    core_tests();
    for (int i = 1; i < argc; i++) {
        plan_tests(argv[i]);
    }
    printf("{\"passed\":true,\"checks\":%u,\"trees\":%u,\"max_exclusions\":%u,"
           "\"optional_property_accepts\":%u,\"optional_property_rejects\":%u,"
           "\"optional_property_size_rejects\":%u,"
           "\"enable_sweep\":{\"reads\":129,\"writes\":252,\"clears\":12},"
           "\"disable_sweep\":{\"reads\":141,\"writes\":63,\"clears\":12},"
           "\"firmware_executed\":false}\n", checks, plan_trees,
           (unsigned)APPLE_MODERN_MAX_BOARD_EXCLUSIONS, opt_accepts, opt_rejects,
           opt_size_rejects);
    return 0;
}
